import React from 'react';

const Layout = ({ children, onNavigate }) => {
  return (
    <div className="min-h-screen bg-[#e3e4e9]" dir="rtl">

      {/* HEADER */}
      <nav className="bg-[#0c1f40] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <img
            src="/logo.png"
            alt="Logo"
            className="h-14 cursor-pointer"
            onClick={() => onNavigate('home')}
          />

          <div className="flex gap-3">
            <button
              onClick={() => onNavigate('signin')}
              className="px-5 py-2 rounded-lg border border-white text-white font-semibold hover:bg-white/10"
            >
              إنشاء حساب
            </button>
            <button
              onClick={() => onNavigate('login')}
              className="px-5 py-2 rounded-lg bg-white text-[#0c1f40] font-semibold hover:bg-gray-100"
            >
              تسجيل الدخول
            </button>
          </div>
        </div>
      </nav>

      {/* CONTENT */}
      <main className="flex-grow">{children}</main>

      {/* FOOTER */}
      <footer className="bg-[#0c1f40] py-6 text-center">
        <p className="text-gray-300 text-sm">
          © 2026 مَكمَن – جميع الحقوق محفوظة
        </p>
      </footer>

    </div>
  );
};

export default Layout;
